import React, { createContext, useState, useContext, ReactNode, useEffect } from 'react';
import { CompanyInfo, Customer, Order, OrderItem, GalleryItem, RecentOrder } from '../types.ts';
import { COMPANY_INFO, CURRENT_CUSTOMER, SAMPLE_ORDER, INITIAL_GALLERY, INITIAL_RECENT_ORDERS } from '../constants.ts';

interface DataContextType {
  companyInfo: CompanyInfo;
  updateCompanyInfo: (info: CompanyInfo) => void;
  customer: Customer;
  updateCustomer: (customer: Customer) => void;
  order: Order;
  updateOrder: (order: Order) => void;
  updateOrderItem: (index: number, field: keyof OrderItem, value: any) => void;
  addOrderItem: () => void;
  removeOrderItem: (index: number) => void;
  updateAmountPaid: (amount: number) => void;
  gallery: GalleryItem[];
  addGalleryItem: (item: Omit<GalleryItem, 'id'>) => void;
  removeGalleryItem: (id: string) => void;
  recentOrders: RecentOrder[];
  removeRecentOrder: (id: string) => void;
  bulkUpdate: (data: { companyInfo?: Partial<CompanyInfo>, customer?: Partial<Customer>, order?: Partial<Order> }) => void;
  isAutoSaving: boolean;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

const loadFromStorage = <T,>(key: string, fallback: T): T => {
  if (typeof window === 'undefined') return fallback;
  try {
    const saved = localStorage.getItem(key);
    return saved ? JSON.parse(saved) : fallback;
  } catch (e) {
    console.warn(`Failed to load ${key} from storage`, e);
    return fallback;
  }
};

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [companyInfo, setCompanyInfo] = useState<CompanyInfo>(() => loadFromStorage('companyInfo', COMPANY_INFO));
  const [customer, setCustomer] = useState<Customer>(() => loadFromStorage('customer', CURRENT_CUSTOMER));
  const [order, setOrder] = useState<Order>(() => loadFromStorage('order', SAMPLE_ORDER));
  const [gallery, setGallery] = useState<GalleryItem[]>(() => loadFromStorage('gallery', INITIAL_GALLERY));
  const [recentOrders, setRecentOrders] = useState<RecentOrder[]>(() => loadFromStorage('recentOrders', INITIAL_RECENT_ORDERS));
  const [isAutoSaving, setIsAutoSaving] = useState(false);

  // Auto-save effect
  useEffect(() => {
    setIsAutoSaving(true);
    const timer = setTimeout(() => {
      localStorage.setItem('companyInfo', JSON.stringify(companyInfo));
      localStorage.setItem('customer', JSON.stringify(customer));
      localStorage.setItem('order', JSON.stringify(order));
      localStorage.setItem('gallery', JSON.stringify(gallery));
      localStorage.setItem('recentOrders', JSON.stringify(recentOrders));
      setIsAutoSaving(false);
    }, 500);

    return () => clearTimeout(timer);
  }, [companyInfo, customer, order, gallery, recentOrders]);

  const updateCompanyInfo = (info: CompanyInfo) => setCompanyInfo(info);
  const updateCustomer = (c: Customer) => setCustomer(c);
  const updateOrder = (o: Order) => setOrder(o);

  const calculateTotals = (items: OrderItem[], amountPaid: number) => {
    const subtotal = items.reduce((sum, i) => sum + i.total, 0);
    const total = subtotal;
    const amountDue = Math.max(0, total - amountPaid);
    return { subtotal, total, amountDue };
  };

  const updateAmountPaid = (amount: number) => {
      setOrder(prev => {
        const { subtotal, total, amountDue } = calculateTotals(prev.items, amount);
        return { ...prev, amountPaid: amount, subtotal, total, amountDue };
      });
  };

  const bulkUpdate = (data: { companyInfo?: Partial<CompanyInfo>, customer?: Partial<Customer>, order?: Partial<Order> }) => {
    if (data.companyInfo) setCompanyInfo(prev => ({ ...prev, ...data.companyInfo }));
    if (data.customer) setCustomer(prev => ({ ...prev, ...data.customer }));
    if (data.order) {
        setOrder(prev => {
            const merged = { ...prev, ...data.order };
            const { subtotal, total, amountDue } = calculateTotals(merged.items, merged.amountPaid);
            return { ...merged, subtotal, total, amountDue };
        });
    }
  };

  const updateOrderItem = (index: number, field: keyof OrderItem, value: any) => {
    setOrder(prev => {
        const newItems = [...prev.items];
        const item = { ...newItems[index] };
        (item as any)[field] = value;
        if (field === 'quantity' || field === 'price') {
           item.total = Number(item.quantity) * Number(item.price);
        }
        newItems[index] = item;
        const { subtotal, total, amountDue } = calculateTotals(newItems, prev.amountPaid);
        return { ...prev, items: newItems, subtotal, total, amountDue };
    });
  };

  const addOrderItem = () => {
    setOrder(prev => {
        const newItem: OrderItem = {
          id: `item_${Date.now()}`,
          description: 'New Item',
          details: [],
          quantity: 1,
          unit: 'each',
          price: 0,
          total: 0
        };
        const newItems = [...prev.items, newItem];
        const { subtotal, total, amountDue } = calculateTotals(newItems, prev.amountPaid);
        return { ...prev, items: newItems, subtotal, total, amountDue };
    });
  };

  const removeOrderItem = (index: number) => {
    setOrder(prev => {
        const newItems = prev.items.filter((_, i) => i !== index);
        const { subtotal, total, amountDue } = calculateTotals(newItems, prev.amountPaid);
        return { ...prev, items: newItems, subtotal, total, amountDue };
    });
  };

  const addGalleryItem = (item: Omit<GalleryItem, 'id'>) => {
    const newItem: GalleryItem = { ...item, id: `g_${Date.now()}` };
    setGallery(prev => [newItem, ...prev]);
  };

  const removeGalleryItem = (id: string) => {
    setGallery(prev => prev.filter(item => item.id !== id));
  };

  const removeRecentOrder = (id: string) => {
    setRecentOrders(prev => prev.filter(order => order.id !== id));
  };

  return (
    <DataContext.Provider value={{ 
        companyInfo, updateCompanyInfo, 
        customer, updateCustomer, 
        order, updateOrder, updateOrderItem,
        addOrderItem, removeOrderItem, updateAmountPaid,
        gallery, addGalleryItem, removeGalleryItem,
        recentOrders, removeRecentOrder,
        bulkUpdate,
        isAutoSaving
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (!context) throw new Error('useData must be used within DataProvider');
  return context;
};

import React, { useRef, useState } from 'react';
import { useData } from '../contexts/DataContext.tsx';
import { OrderItem } from '../types.ts';
import { Image, Upload, Trash2, Plus, Cloud, Check, Camera, Loader2 } from 'lucide-react';

type DocumentMode = 'order' | 'invoice' | 'receipt';

interface DocumentLayoutProps {
  title: string;
  documentNumber: string;
  onDocumentNumberChange?: (val: string) => void;
  dateLabel: string;
  dateValue: string;
  onDateChange?: (val: string) => void;
  dueDateValue: string;
  onDueDateChange?: (val: string) => void;
  customerNoValue: string;
  onCustomerNoChange?: (val: string) => void;
  children?: React.ReactNode;
  mode: DocumentMode;
  isEditing?: boolean;
}

export const EditableInput = ({ value, onChange, className = "", type = "text", placeholder = "", align = "left" }: any) => (
  <input
    type={type}
    value={value}
    onChange={(e) => onChange(e.target.value)}
    placeholder={placeholder}
    className={`
      transition-all duration-200
      bg-transparent border-b border-dashed border-gray-300 hover:border-blue-400 hover:bg-blue-50/50
      focus:outline-none focus:border-blue-500 focus:ring-0 focus:bg-white focus:shadow-sm
      px-1 py-0.5 w-full rounded-sm
      ${align === 'right' ? 'text-right' : align === 'center' ? 'text-center' : 'text-left'}
      ${className}
    `}
  />
);

export const EditableTextArea = ({ value, onChange, className = "" }: any) => (
  <textarea
    value={value}
    onChange={(e) => onChange(e.target.value)}
    rows={2}
    className={`
      transition-all duration-200
      bg-transparent border border-dashed border-gray-300 hover:border-blue-400 hover:bg-blue-50/50
      focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 focus:bg-white
      rounded px-2 py-1 w-full resize-none
      ${className}
    `}
  />
);

const DocumentLayout: React.FC<DocumentLayoutProps> = ({ 
  title, 
  documentNumber, 
  onDocumentNumberChange,
  dateLabel, 
  dateValue,
  onDateChange,
  dueDateValue,
  onDueDateChange,
  customerNoValue,
  onCustomerNoChange,
  children,
  mode,
  isEditing = false
}) => {
  const { 
    companyInfo, updateCompanyInfo, 
    customer, updateCustomer, 
    order, updateOrderItem,
    addOrderItem, removeOrderItem, updateAmountPaid,
    addGalleryItem,
    isAutoSaving
  } = useData();

  const fileInputRef = useRef<HTMLInputElement>(null);
  const docRef = useRef<HTMLDivElement>(null);
  const [isCapturing, setIsCapturing] = useState(false);

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateCompanyInfo({ ...companyInfo, logoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddressChange = (index: number, value: string, isCompany: boolean) => {
    if (isCompany) {
      const newAddr = [...companyInfo.address];
      newAddr[index] = value;
      updateCompanyInfo({ ...companyInfo, address: newAddr });
    } else {
      const newAddr = [...customer.address];
      newAddr[index] = value;
      updateCustomer({ ...customer, address: newAddr });
    }
  };

  const handleCapture = async () => {
      if (!docRef.current) return;

      // Safety check for script readiness
      if (!(window as any).html2canvas) {
          alert("Capture utility is still loading. Please try again in a moment.");
          return;
      }

      setIsCapturing(true);
      try {
          // @ts-ignore
          const canvas = await window.html2canvas(docRef.current, {
              scale: 2,
              useCORS: true,
              logging: false,
              backgroundColor: '#ffffff'
          });
          const imgData = canvas.toDataURL('image/jpeg', 0.8);
          addGalleryItem({
              url: imgData,
              caption: `Screenshot of ${title} #${documentNumber}`,
              date: new Date().toLocaleDateString('en-GB'),
              type: 'capture'
          });
          // Non-blocking success notification
          console.log("Snapshot saved to gallery");
      } catch (err) {
          console.error("Capture failed", err);
          alert("Failed to capture screenshot. Please try again.");
      } finally {
          setIsCapturing(false);
      }
  };

  let statusText = "UNPAID";
  let statusColor = "text-red-600 border-red-600";
  if (order.amountDue <= 0 && order.total > 0) {
      statusText = "PAID";
      statusColor = "text-green-600 border-green-600";
  } else if (order.amountPaid > 0) {
      statusText = "PARTIAL";
      statusColor = "text-orange-500 border-orange-500";
  }
  if (mode === 'receipt') {
      statusText = "PAID IN FULL";
      statusColor = "text-green-600 border-green-600";
  }

  return (
    <div className="relative">
      {/* Floating Capture Button */}
      {!isEditing && (
          <button 
            onClick={handleCapture}
            disabled={isCapturing}
