                      <EditableInput value={companyInfo.regNo} onChange={(v: string) => updateCompanyInfo({...companyInfo, regNo: v})} className="w-full max-w-[140px]" align="right" />
                  </div>
                  <div className="flex items-center gap-2 w-full justify-end">
