                  </div>
                  <div className="flex items-center gap-2 w-full justify-end">
                      <span>Web:</span>
                      <EditableInput value={companyInfo.website} onChange={(v: string) => updateCompanyInfo({...companyInfo, website: v})} className="w-full max-w-[180px]" align="right" />
